#include <stdio.h>
struct Stock { int available; };
int can_sell(const struct Stock *stock, int requested) {
 return stock != NULL && requested > 0 && requested <= stock->available;
}
int main(void) {
 struct Stock item = {6};
 printf("%s\n", can_sell(&item, 2) ? "available" : "not available");
 return 0;
}
